from pathlib import Path
import json

base=Path('projects/a-right-little-something').resolve()
chorus=json.loads((base/'kling-chorus1-motion-v01.json').read_text())
lock='PROMPT LOCK:'+chorus['shots'][0]['prompt'].split('PROMPT LOCK:',1)[1]
prompt="""One uninterrupted six-second exterior wide illustrated shot from this exact starting image. Keep the immense turquoise/peach living world's curved horizon and dark spires filling the lower-left, with the ONE small spherical spacecraft in the upper-right. Preserve the original geography, composition, tiny human scale and the precise ship silhouette throughout. Motion is already present in the first frame: cloud banks drift slowly along the existing coast, small cloud edges curl, and light glides subtly over the cloud tops. Fine highlights shimmer on the distant turquoise water without redrawing its channels or changing the terrain. The whole ship drifts very gently toward the upper-right by only about two percent of frame width over six seconds, without turning, spinning or banking. Its upper and lower platforms, continuous equatorial metal band and aft open engine ring remain solid and coherent. Harper <<<323570155312565>>> stays the same tiny auburn-haired adult in gray clothing floating inside: quiet breathing, a small floating weight shift and slight hair movement, no large gesture, no foreground face, no growth or pose change. The ultra-thin cyan geodesic field has faint flowing light, not thick glass or bubble refraction. The cyan engine arc has restrained living energy, steady amber rim lamps and gentle illustrated bloom; no flashing or thrust plume. The upper-right light source, stars and violet nebula stay anchored. The world feels enormous and alive around this small observer. LOCKED camera: no pan, zoom, pullback, jiggle, shake, cut, internal fade, zoom blur or reframing. We will apply one deliberate Ken Burns opening move in the edit afterwards. Keep generous room across the entire original frame for that crop. No added moons, planets, ships, navigation lines, labels, text, audio, HUD or new equipment. Preserve the painterly graphic-novel finish.
""".strip()+'\n\n'+lock
shot=dict(id='scale-reveal-motion-v01',shotId='scale-reveal-new',title='Show you just how big you are / living scale reveal',startFrame=854,editFrames=58,leadInFrames=24,leadOutFrames=24,model='kling-video-v3_0',duration=6,resolution='1080p',imageCount=1,enable_audio=False,prefer_multi_shots=False,tailImage=None,firstImage='generated/storyboard/chorus-revision-v02/scale-reveal-v02.png',elements=[dict(id='323570155312565',bindName='Harper')],prompt=prompt)
plan=dict(status='Prepared for the user-requested replacement of the reviewed scale still',fps=24,output='generated/kling-tests/scale-motion-v01',reviewOutput='generated/storyboard/scale-motion-v01',estimatedCredits=48,authorization='User explicitly requested replacing the reviewed scale-reveal still with a Kling video, 2026-10-10.',timingSource='Existing DAWproject-derived phrase starts: 854-912, 58 frames at 24fps, with 24-frame source handles.',reviewChecks='Cloud motion and water light; subtle ship/Harper motion; coherent metal platforms, thin field and engine ring. Camera move is editorial. No geometry morph or new sky object.',shots=[shot])
assert prompt.endswith(lock)
assert shot['duration']*plan['fps']>=shot['leadInFrames']+shot['editFrames']+shot['leadOutFrames']
(base/'kling-scale-motion-v01.json').write_text(json.dumps(plan,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
print('Prepared one 6-second 1080p take, estimated 48 credits; 58-frame edit with 24-frame handles; original prompt lock retained')
